"""Regenerate patched S3 operations and COPY result DTOs from reviewed templates."""

from __future__ import annotations

import argparse
import re

from tools.artifacts import ROOT

VENDOR = ROOT / "vendor/s3s-0.17.0"
HEADER = """// SPDX-License-Identifier: Apache-2.0
// SPDX-FileCopyrightText: 2023-2026 The s3s Authors

//! Generated by tools/regenerate_s3s.py from codegen/{stem}.rs.in.

"""


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    arguments = parser.parse_args()
    dto_path = VENDOR / "src/dto/generated.rs"
    dto = dto_path.read_text(encoding="utf-8")
    outputs = {}

    for stem in (
        "copy_object",
        "upload_part_copy",
        "get_object",
        "head_object",
        "post_object",
    ):
        outputs[VENDOR / f"src/ops/generated/{stem}.rs"] = HEADER.format(stem=stem) + (
            VENDOR / f"codegen/{stem}.rs.in"
        ).read_text(encoding="utf-8")

    for stem, name in (
        ("copy_object", "CopyObjectOutput"),
        ("upload_part_copy", "UploadPartCopyOutput"),
    ):
        fragment = (
            (VENDOR / f"codegen/{stem}_output.rs.in")
            .read_text(encoding="utf-8")
            .rstrip()
        )

        def replace_fragment(_: re.Match[str], fragment: str = fragment) -> str:
            return fragment

        dto, count = re.subn(
            rf"^#\[derive\([^\n]+\)\]\npub struct {name} \{{.*?^\}}",
            replace_fragment,
            dto,
            flags=re.MULTILINE | re.DOTALL,
        )

        if count != 1:
            raise ValueError(f"missing or ambiguous {name} generation boundary")

        note = f"//! {name} is generated by tools/regenerate_s3s.py from codegen/{stem}_output.rs.in.\n"

        if note not in dto:
            marker = "//! Auto generated by `s3s_codegen::v1::dto::codegen`\n"

            if dto.count(marker) != 1:
                raise ValueError("missing DTO generator marker")

            dto = dto.replace(marker, marker + note)

    outputs[dto_path] = dto

    for path, expected in outputs.items():
        if arguments.check:
            if path.read_text(encoding="utf-8") != expected:
                print(f"Patched S3 source needs regeneration: {path.relative_to(ROOT)}")

                return 1
        else:
            path.write_text(expected, encoding="utf-8", newline="\n")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
